$('#newMapBtn')?.addEventListener('click',openMapCollectionMenu);
$('#emptyCreateMap')?.addEventListener('click',()=>newMapDialog());
$('#mapRail').oncontextmenu=e=>{if(e.target.closest('.map-tree-map-row,.map-tree-line-row'))return;openMapCollectionMenu(e)};
$('#toggleMapRail')?.addEventListener('click',toggleMapRail);
$('#mapViewBtn')?.addEventListener('pointerdown',e=>e.preventDefault());$('#mapViewBtn')?.addEventListener('click',e=>{e.stopPropagation();toggleMapViewPopover()});$('#mapMetroViewBtn')?.addEventListener('click',openMetroView);$('#editMapDetailsBtn')?.addEventListener('click',()=>configureCurrentMap());
$('#mapZoomOut')?.addEventListener('click',()=>setMapZoom(state.mapZoom-.15));$('#mapZoomIn')?.addEventListener('click',()=>setMapZoom(state.mapZoom+.15));$('#mapZoomReset')?.addEventListener('click',()=>setMapZoom(1));$('#mapZoomFit')?.addEventListener('click',()=>{fitMap();closeMapViewPopover()});
$('#mapViewOrientation')?.addEventListener('click',()=>{const current=state.mapData?.map?.orientation||'horizontal';setMapSetting('orientation',current==='horizontal'?'vertical':'horizontal','Change Map orientation')});$('#mapViewLayout')?.addEventListener('click',()=>{const current=state.mapData?.map?.layout_mode||'scaled';setMapSetting('layout_mode',current==='scaled'?'schematic':'scaled','Change Map layout')});$('#mapViewLabels')?.addEventListener('click',()=>{const modes=['minimal','full','hidden'],current=state.mapData?.map?.label_mode||'minimal',index=modes.indexOf(current);setMapSetting('label_mode',modes[(index+1+modes.length)%modes.length],'Change Map labels')});$('#mapRulerScale')?.addEventListener('input',e=>applyMapRulerScale(entityId(e.currentTarget.value)/100));$('#mapTextSize')?.addEventListener('input',e=>applyMapTextSize(e.currentTarget.value));$('#mapFont')?.addEventListener('change',e=>applyMapFont(e.currentTarget.value));
window.addEventListener('resize',positionMapViewPopover,{passive:true});window.addEventListener('scroll',positionMapViewPopover,true);
document.addEventListener('keydown',event=>{if(!$('#mapsView')?.classList.contains('active'))return;const typing=event.target.matches?.('input,textarea,select,[contenteditable]'),interactiveControl=!!event.target.closest?.('button,a'),shortcut=(event.metaKey||event.ctrlKey)&&!event.altKey&&!event.shiftKey&&!event.repeat,key=String(event.key||'').toLowerCase();if((event.key==='Delete'||event.key==='Backspace')&&!typing&&!interactiveControl&&!event.metaKey&&!event.ctrlKey&&!event.altKey&&!event.repeat){let action=null;if(state.selectedMapJunctionId){const junction=state.mapData?.junctions?.find(row=>row.id===state.selectedMapJunctionId);if(junction)action=()=>deleteMapJunction(junction)}else if(state.selectedMapItemId){const found=mapItemById(state.selectedMapItemId);if(found)action=()=>deleteMapItem(found.item,found.line)}else if(state.currentMapLineId){const line=mapLineById(state.currentMapLineId);if(line)action=()=>deleteMapLine(line)}if(action){event.preventDefault();event.stopPropagation();Promise.resolve(action()).catch(error=>{console.error('MAP_DELETE_KEY_001',error);toast(error.message||'Map item could not be deleted.')});return}}if(!shortcut||typing)return;if(key==='c'&&copySelectedMapLine()){event.preventDefault();return}if(key==='v'&&state.mapLineClipboard?.lineId){event.preventDefault();pasteMapLine().catch(error=>{console.error('MAP_LINE_PASTE_001',error);toast(error.message||'Line could not be pasted.')})}},true);
$('#mapStage')?.addEventListener('wheel',e=>{if(!(e.ctrlKey||e.metaKey))return;e.preventDefault();setMapZoom(state.mapZoom+(e.deltaY<0?.1:-.1))},{passive:false});
$('#mapStage')?.addEventListener('scroll',queueMapViewportPersist,{passive:true});
$('#mapStage')?.addEventListener('dblclick',e=>{if(state.mapPendingConnection)return;e.preventDefault();clearMapLineFocus()});
$('#mapEmpty')?.addEventListener('contextmenu',async e=>{if(!state.currentMap)return;e.preventDefault();try{await loadMapPopulateCatalog()}catch{}openContextMenu(e.clientX,e.clientY,mapBackgroundMenu())});


async function jumpToScene(sceneId){
  const scene=state.scenes.find(s=>entityId(s.id)===entityId(sceneId));if(!scene)return;
  const chapterId=scene.first_chapter_id||scene.chapter_id;if(chapterId)await selectChapter(entityId(chapterId),false);
  requestAnimationFrame(()=>{const el=$(`.manuscript-block-wrap[data-scene-id="${sceneId}"]`);if(el)revealOutlineTarget(el);el?.scrollIntoView({block:'center',behavior:'smooth'});});
}
